// The mounted-flag fix for browser-dependent UI
'use client';
import { useSyncExternalStore } from 'react';

// SSR-safe 'is client' — returns false on server, true after hydration
const useIsClient = () =>
  useSyncExternalStore(() => () => {}, () => true, () => false);

export function LocalTime({ iso }: { iso: string }) {
  const isClient = useIsClient();
  return (
    <time dateTime={iso} suppressHydrationWarning>
      {isClient ? new Date(iso).toLocaleString() : iso /* stable server output */}
    </time>
  );
}

