// middleware.ts — hostname -> internal tenant path
import { NextResponse, type NextRequest } from 'next/server';

export function middleware(req: NextRequest) {
  const host = req.headers.get('host') ?? '';
  const sub = host.split('.')[0];                  // acme.app.com -> 'acme'
  if (!sub || ['www', 'app'].includes(sub)) return NextResponse.next();

  const url = req.nextUrl.clone();
  url.pathname = `/t/${sub}${url.pathname}`;       // rewrite, URL bar unchanged
  return NextResponse.rewrite(url);
}

